package com.mohymods.kingdomsmp.equipment;
import com.mohymods.kingdomsmp.economy.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.common.util.BlockSnapshot;
import net.neoforged.neoforge.event.EventHooks;
import net.neoforged.neoforge.event.level.BlockEvent;
import net.neoforged.neoforge.common.NeoForge;
import java.io.IOException;
import java.util.*;
/** World-before-player save ordering plus canonical receipt recovery. Unknown changes quarantine, never guess/refund. */
public final class MasterWorldWork {
 private record Reservation(String dimension,Set<Long> cells) { }
 private static final Map<MinecraftServer,Reservation> RESERVED=new WeakHashMap<>();
 private static final ThreadLocal<Boolean> APPLYING=ThreadLocal.withInitial(()->false);
 private MasterWorldWork(){ }
 public static void resolved(MinecraftServer server,EconomyStore store){if(store.pendingMasterWork().isEmpty())RESERVED.remove(server);}
 public static boolean protectedAt(ServerLevel level,BlockPos pos){var r=RESERVED.get(level.getServer());return !APPLYING.get()&&r!=null&&r.dimension().equals(level.dimension().location().toString())&&r.cells().contains(pos.asLong());}
 private static BlockState state(ServerLevel level,CompoundTag row,String key){var tag=row.getCompound(key);if(!tag.contains("Name",Tag.TAG_STRING))throw new IllegalArgumentException("Missing world block ID");var id=net.minecraft.resources.ResourceLocation.parse(tag.getString("Name"));if(!net.minecraft.core.registries.BuiltInRegistries.BLOCK.containsKey(id))throw new IllegalArgumentException("Unknown world block ID");var state=NbtUtils.readBlockState(level.registryAccess().lookupOrThrow(Registries.BLOCK),tag);if(!NbtUtils.writeBlockState(state).equals(tag))throw new IllegalArgumentException("Noncanonical world block state");return state;}
 private static void reserve(ServerLevel level,ListTag cells){var positions=new HashSet<Long>();for(var value:cells)if(!positions.add(((CompoundTag)value).getLong("position")))throw new IllegalArgumentException("Duplicate world position");RESERVED.put(level.getServer(),new Reservation(level.dimension().location().toString(),Set.copyOf(positions)));}
 public static void apply(ServerPlayer p,ListTag cells)throws IOException{if(cells.isEmpty())return;var level=p.serverLevel();if(level.noSave)throw new IllegalStateException("Enable world saving before Wand work");reserve(level,cells);APPLYING.set(true);try{
  for(var value:cells){var row=(CompoundTag)value;var at=BlockPos.of(row.getLong("position"));var before=state(level,row,"before");if(!MasterToolService.permitted(p,at)||!level.getBlockState(at).equals(before)||!level.getEntities(null,new net.minecraft.world.phys.AABB(at)).isEmpty())throw new IllegalStateException("World/claims/collision changed before placement");}
  for(var value:cells){var row=(CompoundTag)value;var at=BlockPos.of(row.getLong("position"));var before=state(level,row,"before");var after=state(level,row,"after");if(!before.isAir()&&NeoForge.EVENT_BUS.post(new BlockEvent.BreakEvent(level,at,before,p)).isCanceled())throw new IllegalStateException("Native block replacement was refused");var snapshot=BlockSnapshot.create(level.dimension(),level,at);if(!level.setBlock(at,after,18)||EventHooks.onBlockPlace(p,snapshot,Direction.UP)||!level.getBlockState(at).equals(after))throw new IllegalStateException("Native block placement was refused");}
  level.getChunkSource().save(true);verifyDisk(level,cells,"after");
 }finally{APPLYING.remove();}}
 private static void verifyDisk(ServerLevel level,ListTag rows,String expected)throws IOException{
  try{var chunks=new HashMap<net.minecraft.world.level.ChunkPos,CompoundTag>();var states=new HashMap<String,net.minecraft.world.level.chunk.PalettedContainer<BlockState>>();var codec=net.minecraft.world.level.chunk.PalettedContainer.codecRW(net.minecraft.world.level.block.Block.BLOCK_STATE_REGISTRY,BlockState.CODEC,net.minecraft.world.level.chunk.PalettedContainer.Strategy.SECTION_STATES,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());
   for(var value:rows){var row=(CompoundTag)value;var at=BlockPos.of(row.getLong("position"));var cp=new net.minecraft.world.level.ChunkPos(at);var chunk=chunks.get(cp);if(chunk==null){chunk=level.getChunkSource().chunkMap.read(cp).join().orElseThrow(()->new IllegalStateException("Wand chunk save missing"));chunks.put(cp,chunk);}String key=cp.toLong()+"/"+(at.getY()>>4);var palette=states.get(key);if(palette==null){for(var s:chunk.getList("sections",Tag.TAG_COMPOUND)){var section=(CompoundTag)s;if(section.getByte("Y")==at.getY()>>4&&section.contains("block_states")){palette=codec.parse(NbtOps.INSTANCE,section.getCompound("block_states")).result().orElseThrow(()->new IllegalStateException("Unreadable saved block palette"));states.put(key,palette);break;}}}var disk=palette==null?net.minecraft.world.level.block.Blocks.AIR.defaultBlockState():palette.get(at.getX()&15,at.getY()&15,at.getZ()&15);if(!disk.equals(state(level,row,expected)))throw new IOException("Wand chunk checkpoint differs from committed targets");}
  }catch(RuntimeException failure){throw new IOException("Wand world checkpoint cannot be verified",failure);}
 }
 public static void beforeRecover(MinecraftServer server,EconomyStore store,EconomyStore.Receipt receipt)throws IOException{var data=store.pendingMasterWork().orElse(null);if(data==null){RESERVED.remove(server);return;}var guarded=data.getList("world",Tag.TAG_COMPOUND);if(!guarded.isEmpty()){var guardedLevel=server.getLevel(net.minecraft.resources.ResourceKey.create(Registries.DIMENSION,net.minecraft.resources.ResourceLocation.parse(data.getString("dimension"))));if(guardedLevel==null)throw new IOException("Wand recovery dimension unavailable");reserve(guardedLevel,guarded);}var transaction=store.pendingItem().orElseThrow();boolean committed=store.id().equals(receipt.store())&&receipt.sequence()==transaction.sequence();boolean original=receipt.sequence()==transaction.previousReceipt()&&(store.id().equals(receipt.store())||receipt.store()==null&&receipt.sequence()==0);if(!committed&&!original)throw new IOException("Master inventory receipt mismatch");if(data.contains("xpState")){var nativePlayer=com.mohymods.kingdomsmp.persistence.AtomicNbt.read(CommerceService.playerFile(server,transaction.player()));var xp=data.getCompound("xpState");if(nativePlayer.getInt("XpLevel")!=xp.getInt(committed?"after":"before")||nativePlayer.getInt("XpTotal")!=xp.getInt("total")||Float.compare(nativePlayer.getFloat("XpP"),xp.getFloat("progress"))!=0)throw new IOException("Master XP checkpoint mismatch");var expected=data.getList(committed?"after":"before",Tag.TAG_COMPOUND);var saved=new ArrayList<CompoundTag>();for(int i=0;i<36;i++)saved.add(new CompoundTag());for(var value:nativePlayer.getList("Inventory",Tag.TAG_COMPOUND)){var slot=((CompoundTag)value).copy();int i=slot.getByte("Slot")&255;if(i<36){slot.remove("Slot");saved.set(i,slot);}}for(int i=0;i<36;i++)if(!saved.get(i).equals(expected.getCompound(i)))throw new IOException("Master inventory snapshot mismatch");}var rows=data.getList("world",Tag.TAG_COMPOUND);if(rows.isEmpty())return;var level=server.getLevel(net.minecraft.resources.ResourceKey.create(Registries.DIMENSION,net.minecraft.resources.ResourceLocation.parse(data.getString("dimension"))));if(level==null)throw new IOException("Wand recovery dimension unavailable");if(level.noSave)throw new IOException("Enable world saving for Wand recovery");var chunks=new HashSet<net.minecraft.world.level.ChunkPos>();for(var value:rows)chunks.add(new net.minecraft.world.level.ChunkPos(BlockPos.of(((CompoundTag)value).getLong("position"))));if(chunks.size()>4)throw new IOException("Wand recovery chunk bound exceeded");reserve(level,rows);var pending=store.pendingItem().orElseThrow();boolean post=store.id().equals(receipt.store())&&receipt.sequence()==pending.sequence();boolean previous=receipt.sequence()==pending.previousReceipt()&&(store.id().equals(receipt.store())||receipt.store()==null&&receipt.sequence()==0);if(!post&&!previous)throw new IOException("Wand inventory receipt mismatch");
  for(var value:rows){var row=(CompoundTag)value;var at=BlockPos.of(row.getLong("position"));if(!level.hasChunkAt(at))level.getChunk(at);var current=level.getBlockState(at);if(!current.equals(state(level,row,"after"))&&(!previous||!current.equals(state(level,row,"before"))))throw new IOException("Wand recovery found an unknown world edit; preserve matching checkpoint");}
  if(previous){APPLYING.set(true);try{for(var value:rows){var row=(CompoundTag)value;var at=BlockPos.of(row.getLong("position"));if(!level.setBlock(at,state(level,row,"before"),18)&&!level.getBlockState(at).equals(state(level,row,"before")))throw new IOException("Wand rollback failed");}level.getChunkSource().save(true);verifyDisk(level,rows,"before");}finally{APPLYING.remove();}}
 }
}
